import sqlite3

con = sqlite3.connect(':memory:')
con.execute('PRAGMA foreign_keys = ON')
con.executescript("""
CREATE TABLE students (id INTEGER PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE courses  (id INTEGER PRIMARY KEY, title TEXT NOT NULL);
CREATE TABLE enrolments (
  student_id INTEGER REFERENCES students(id),
  course_id  INTEGER REFERENCES courses(id),
  PRIMARY KEY (student_id, course_id)
);
INSERT INTO students VALUES (1, 'Amina'), (2, 'Ben');
INSERT INTO courses  VALUES (10, 'Databases');
INSERT INTO enrolments VALUES (1, 10);
""")
try:
    con.execute('INSERT INTO enrolments VALUES (99, 10)')  # student 99 does not exist
except sqlite3.IntegrityError as e:
    print('Rejected by the database:', e)

