import sqlite3

con = sqlite3.connect(':memory:')
con.execute('CREATE TABLE items (name TEXT PRIMARY KEY, qty INTEGER)')

n = int(input())
for _ in range(n):
    parts = input().split()
    cmd = parts[0]
    if cmd == 'add':
        name, q = parts[1], int(parts[2])
        con.execute('INSERT INTO items (name, qty) VALUES (?, ?) '
                    'ON CONFLICT (name) DO UPDATE SET qty = qty + excluded.qty',
                    (name, q))
    elif cmd == 'sell':
        name, q = parts[1], int(parts[2])
        cur = con.execute('UPDATE items SET qty = qty - ? WHERE name = ? AND qty >= ?',
                          (q, name, q))
        if cur.rowcount == 0:
            print(f'cannot sell {name}')
    elif cmd == 'remove':
        name = parts[1]
        cur = con.execute('DELETE FROM items WHERE name = ?', (name,))
        if cur.rowcount == 0:
            print(f'no {name}')
    elif cmd == 'show':
        rows = con.execute('SELECT name, qty FROM items ORDER BY name').fetchall()
        if not rows:
            print('(empty)')
        for name, qty in rows:
            print(name, qty)

