import sqlite3

con = sqlite3.connect(':memory:')
con.executescript("""
CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT, address TEXT);
CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER REFERENCES customers(id));
INSERT INTO customers VALUES (1, 'Ana', '1 Sun St');
INSERT INTO orders VALUES (1, 1), (2, 1), (3, 1);
""")
# Ana moves: ONE update, and every order sees the new address
con.execute("UPDATE customers SET address = '9 Moon Rd' WHERE id = 1")
q = 'SELECT o.id, c.name, c.address FROM orders o JOIN customers c ON c.id = o.customer_id'
for row in con.execute(q):
    print(row)

